117	/// Run one mode step and apply it. Returns true if the pet actually moved.
118	async function stepMode(mode: RoamMode): Promise<boolean> {
119	  const env = await fetchEnvironment(mode === "climb");
120	  if (!env) return false;
121	  const pos = await currentLogicalPos();
122	  if (!pos) return false;
123	
124	  const next = await runMode(mode, { env, pos, pet: petRef });
125	  const clamped = clampToBounds(next, env.workArea);
126	  if (Math.abs(clamped.x - pos.x) < 0.5 && Math.abs(clamped.y - pos.y) < 0.5) {
127	    return false;
128	  }
129	  lastMoveTs = Date.now();
130	  try { await setLogical(clamped); }
131	  catch (e) { void invoke("log_debug", { msg: `roam: setPosition error: ${e}` }).catch(() => {}); }
132	  return true;
133	}
134	
135	/// Pet is stationary (mode is stay or roaming disabled): maybe doze off.
136	function handleStationary(): void {
137	  if (mood === "idle" && Date.now() - lastMoveTs > SLEEP_AFTER_MS) {
138	    enterSleep();
139	  } else {
140	    wake();
141	    petRef?.clearRow();
142	  }
143	}
144	
145	async function handleDragRelease(vel: { vx: number; vy: number }): Promise<void> {
146	  const cfg = loadConfig();
147	  const env = await fetchEnvironment(cfg.mode === "climb");
148	  if (!env) return;
149	
150	  if (cfg.mode === "climb" && env.windows.length > 0) {
151	    const surfaces = env.windows.map((w) => w.rect);
152	    await applyFall(vel.vx, env.workArea, surfaces, petRef, stop);
153	  } else {
154	    await applyThrow(vel.vx, vel.vy, env.workArea, petRef, stop);
155	  }
156	}
157	
158	async function loop(): Promise<void> {
159	  while (!stopRequested) {
160	    const active = await tick();
161	    await sleep(active ? TICK_MS : IDLE_TICK_MS);
162	  }
163	  petRef?.clearRow();
164	}
