166	export function initEngine(pet: Pet): void {
167	  if (petRef) return;
168	  petRef = pet;
169	  stopRequested = false;
170	  lastMoveTs = Date.now();
171	  mood = "idle";
172	  sleeping = false;
173	  void loop();
174	}
175	
176	export function destroyEngine(): void {
177	  stopRequested = true;
178	  cancelThrow();
179	  petRef = null;
180	}
181	
182	export function setDragging(isDragging: boolean): void {
183	  dragging = isDragging;
184	  if (isDragging) {
185	    cancelThrow();
186	    clearSamples();
187	    wake();
188	    releasePending = false;
189	  } else if (petRef) {
190	    releasePending = true;
191	  }
192	}
  1	// Environment sensing: monitor work area + enumeration of other application
  2	// windows. All geometry is returned in logical pixels so the rest of the roam
  3	// subsystem can stay DPI-agnostic.
  4	
  5	import { currentMonitor, type Monitor } from "@tauri-apps/api/window";
  6	import { invoke } from "@tauri-apps/api/core";
  7	import type { Environment, Rect, SystemWindow } from "./types";
  8	
  9	/// Raw shape returned by the Rust `list_system_windows` command. Coordinates
 10	/// are physical pixels; we convert to logical in `fetchEnvironment`.
 11	interface RawSystemWindow {
 12	  title: string;
 13	  x: number;
 14	  y: number;
 15	  width: number;
 16	  height: number;
 17	}
 18	
 19	function toLogicalRect(rect: RawSystemWindow, sf: number): SystemWindow {
 20	  return {
 21	    title: rect.title,
 22	    rect: {
 23	      left: rect.x / sf,
 24	      top: rect.y / sf,
 25	      right: (rect.x + rect.width) / sf,
 26	      bottom: (rect.y + rect.height) / sf,
 27	    },
 28	  };
 29	}
 30	
 31	// 500ms monitor cache: the monitor rarely changes (only when the user drags
 32	// the pet to another display), and currentMonitor() is an IPC call. Without
 33	// this, N roaming pets fire 2×N×33 IPC calls/sec just for monitor info.
 34	const MONITOR_CACHE_MS = 500;
 35	let monitorCache: { mon: Monitor | null; ts: number } | null = null;
 36	
 37	async function cachedMonitor(): Promise<Monitor | null> {
 38	  const now = Date.now();
 39	  if (monitorCache && now - monitorCache.ts < MONITOR_CACHE_MS) {
 40	    return monitorCache.mon;
 41	  }
 42	  try {
 43	    const m = await currentMonitor();
 44	    monitorCache = { mon: m, ts: now };
 45	    return m;
 46	  } catch {
 47	    return null;
 48	  }
 49	}
 50	
 51	// 500ms system-windows cache: list_system_windows is an IPC call that enumerates
 52	// every visible window. Other apps' window positions change far less often than
 53	// the 30ms roam tick, so caching avoids ~33 IPC calls/sec per roaming pet. The
 54	// cache is keyed by the monitor scale factor so a monitor switch still refetches.
 55	const WIN_CACHE_MS = 500;
 56	let winCache: { sf: number; windows: SystemWindow[]; ts: number } | null = null;
 57	
 58	async function fetchSystemWindows(sf: number): Promise<SystemWindow[]> {
 59	  const now = Date.now();
 60	  if (winCache && winCache.sf === sf && now - winCache.ts < WIN_CACHE_MS) {
 61	    return winCache.windows;
 62	  }
 63	  try {
 64	    const raw = await invoke<RawSystemWindow[]>("list_system_windows");
 65	    if (!Array.isArray(raw)) return winCache?.windows ?? [];
 66	    const windows = raw
 67	      .filter((w) => w.width > 40 && w.height > 40)
 68	      .map((w) => toLogicalRect(w, sf));
 69	    winCache = { sf, windows, ts: now };
 70	    return windows;
 71	  } catch {
 72	    return winCache?.windows ?? [];
 73	  }
 74	}
 75	
 76	export function invalidateEnvironmentCache(): void {
 77	  winCache = null;
 78	  monitorCache = null;
 79	}
 80	
 81	export async function fetchEnvironment(includeSystemWindows = false): Promise<Environment | null> {
 82	  try {
 83	    // Single currentMonitor() call (cached) instead of the previous two.
 84	    const m = await cachedMonitor();
 85	    if (!m || !m.workArea) return null;
 86	    const sf = m.scaleFactor || 1;
 87	    const wa = m.workArea;
 88	    const workArea: Rect = {
 89	      left: wa.position.x / sf,
 90	      top: wa.position.y / sf,
 91	      right: (wa.position.x + wa.size.width) / sf,
 92	      bottom: (wa.position.y + wa.size.height) / sf,
 93	    };
 94	
 95	    const windows = includeSystemWindows ? await fetchSystemWindows(sf) : [];
 96	    return { workArea, windows };
 97	  } catch (e) {
 98	    void invoke("log_debug", { msg: `roam: environment error: ${e}` }).catch(() => {});
 99	    return null;
100	  }
101	}
  1	// Drag-release throw physics and gravity-driven fall. Both operate in logical
  2	// pixels per second and are decoupled from the window API so they can be unit
  3	// tested without a live Tauri window.
  4	
  5	import { invoke } from "@tauri-apps/api/core";
  6	import type { Pet } from "../pet";
  7	import type { Point, Rect } from "./types";
  8	import {
  9	  DT_SEC,
 10	  PHYSICS_FRICTION,
 11	  PHYSICS_GRAVITY,
 12	  PHYSICS_MIN_SPEED,
 13	  SAMPLE_WINDOW_MS,
 14	  TICK_MS,
 15	  WIN_H,
 16	  WIN_W,
 17	  sleep,
 18	} from "./types";
 19	import { currentLogicalPos, setLogical } from "./window";
 20	
 21	interface Sample { t: number; x: number; y: number }
 22	const samples: Sample[] = [];
 23	
 24	export function recordSample(pos: Point): void {
 25	  const now = performance.now();
 26	  samples.push({ t: now, x: pos.x, y: pos.y });
 27	  while (samples.length && now - samples[0].t > SAMPLE_WINDOW_MS) samples.shift();
 28	}
 29	
 30	export function releaseVelocity(): { vx: number; vy: number } | null {
 31	  if (samples.length < 2) return null;
 32	  const first = samples[0];
 33	  const last = samples[samples.length - 1];
 34	  const dt = last.t - first.t;
 35	  if (dt < 20) return null;
 36	  return {
 37	    vx: ((last.x - first.x) / dt) * 1000,
 38	    vy: ((last.y - first.y) / dt) * 1000,
 39	  };
 40	}
 41	
 42	export function clearSamples(): void {
 43	  samples.length = 0;
 44	}
 45	
 46	let throwing = false;
 47	export function isThrowing(): boolean { return throwing; }
 48	export function cancelThrow(): void { throwing = false; }
 49	
 50	/// Inertia after a drag release. Friction decays velocity each tick; hitting a
 51	/// screen edge reflects velocity at 50% to feel bouncy without escaping.
 52	export async function applyThrow(
 53	  vx: number,
 54	  vy: number,
 55	  bounds: Rect,
 56	  pet: Pet | null,
 57	  stop: () => boolean,
 58	): Promise<void> {
 59	  throwing = true;
 60	  let pos = await currentLogicalPos();
 61	  if (!pos) { throwing = false; return; }
 62	
 63	  while (!stop() && throwing) {
 64	    if (Math.hypot(vx, vy) < PHYSICS_MIN_SPEED) break;
 65	
 66	    vx *= PHYSICS_FRICTION;
 67	    vy *= PHYSICS_FRICTION;
 68	
 69	    let nx: number = pos.x + vx * DT_SEC;
 70	    let ny: number = pos.y + vy * DT_SEC;
 71	    [vx, nx] = bounceX(vx, nx, bounds);
 72	    [vy, ny] = bounceY(vy, ny, bounds);
 73	
 74	    pos = { x: nx, y: ny };
 75	    try { await setLogical(pos); }
 76	    catch (e) { void invoke("log_debug", { msg: `roam: throw error: ${e}` }).catch(() => {}); break; }
 77	
 78	    pet?.setRow(vx > 0 ? 1 : 2);
 79	    await sleep(TICK_MS);
 80	  }
 81	
 82	  throwing = false;
 83	  pet?.clearRow();
 84	}
 85	
 86	/// Gravity fall after drag release (Shimeji-style). Pet accelerates downward
 87	/// until it lands on a surface (work area bottom or a window top edge).
 88	export async function applyFall(
 89	  vx: number,
 90	  bounds: Rect,
 91	  surfaces: Rect[],
 92	  pet: Pet | null,
 93	  stop: () => boolean,
 94	): Promise<void> {
 95	  throwing = true;
 96	  let pos = await currentLogicalPos();
 97	  if (!pos) { throwing = false; return; }
 98	
 99	  let vy = 0;
100	  while (!stop() && throwing) {
101	    vy += PHYSICS_GRAVITY * DT_SEC;
102	    const nx: number = pos.x + vx * DT_SEC;
103	    let ny: number = pos.y + vy * DT_SEC;
104	
105	    const floorY = findFloor(pos.x, nx, bounds, surfaces);
106	    if (ny >= floorY) {
107	      ny = floorY;
108	      throwing = false;
109	    }
110	
111	    pos = { x: Math.max(bounds.left, Math.min(bounds.right - WIN_W, nx)), y: ny };
112	    try { await setLogical(pos); }
113	    catch (e) { void invoke("log_debug", { msg: `roam: fall error: ${e}` }).catch(() => {}); break; }
114	
115	    pet?.setRow(vx > 0 ? 1 : 2);
116	    await sleep(TICK_MS);
117	  }
118	
119	  throwing = false;
120	  pet?.clearRow();
121	}
122	
123	function bounceX(vx: number, nx: number, bounds: Rect): [number, number] {
124	  if (nx < bounds.left || nx > bounds.right - WIN_W) {
125	    return [-vx * 0.5, Math.max(bounds.left, Math.min(bounds.right - WIN_W, nx))];
126	  }
127	  return [vx, nx];
128	}
129	
130	function bounceY(vy: number, ny: number, bounds: Rect): [number, number] {
131	  if (ny < bounds.top || ny > bounds.bottom - WIN_H) {
132	    return [-vy * 0.5, Math.max(bounds.top, Math.min(bounds.bottom - WIN_H, ny))];
133	  }
134	  return [vy, ny];
135	}
136	
137	/// Find the highest surface (window top edge or work-area bottom) under the
138	/// pet's horizontal range [x1, x2], returned as the pet's TOP-Y when resting on
139	/// it. `pos.y` is the window's top-left, so landing = top at `surface.top - WIN_H`.
140	function findFloor(x1: number, x2: number, bounds: Rect, surfaces: Rect[]): number {
141	  let floor = bounds.bottom - WIN_H;
142	  for (const s of surfaces) {
143	    if (x2 < s.left || x1 > s.right) continue;
144	    const top = s.top - WIN_H;
145	    if (top < floor && top >= bounds.top) floor = top;
146	  }
147	  return floor;
148	}
