  1	// Movement strategies. Each mode is a pure function: given the current
  2	// position and environment, return the next position (and animate the pet).
  3	// The engine drives the tick loop; modes stay stateless where possible.
  4	
  5	import { cursorPosition } from "@tauri-apps/api/window";
  6	import type { Pet } from "../pet";
  7	import type { Environment, Point, Rect, RoamMode } from "./types";
  8	import {
  9	  DT_SEC,
 10	  IDLE_MS_MAX,
 11	  IDLE_MS_MIN,
 12	  MARGIN,
 13	  WIN_H,
 14	  WIN_W,
 15	  clampToBounds,
 16	  loadConfig,
 17	  pxPerSec,
 18	} from "./types";
 19	
 20	const ROW_RIGHT = 1;
 21	const ROW_LEFT = 2;
 22	
 23	export interface ModeContext {
 24	  env: Environment;
 25	  pos: Point;
 26	  pet: Pet | null;
 27	}
 28	
 29	/// Dispatches to the active mode and returns the next position (or the
 30	/// unchanged position if the mode didn't move). Each mode handles its own
 31	/// animation row; if no movement happens, the caller clears the row.
 32	export async function runMode(mode: RoamMode, ctx: ModeContext): Promise<Point> {
 33	  switch (mode) {
 34	    case "stay": return ctx.pos;
 35	    case "cursor": return followCursor(ctx);
 36	    case "climb": return climb(ctx);
 37	    case "wander":
 38	    default: return wander(ctx);
 39	  }
 40	}
 41	
 42	/// Chase the mouse cursor. Stops beside it so it doesn't cover the pointer.
 43	async function followCursor(ctx: ModeContext): Promise<Point> {
 44	  const { env, pos, pet } = ctx;
 45	  try {
 46	    const sf = (await import("@tauri-apps/api/window")).getCurrentWindow();
 47	    const factor = await sf.scaleFactor();
 48	    const cur = await cursorPosition();
 49	    const target = {
 50	      x: cur.x / factor - WIN_W / 2,
 51	      y: cur.y / factor - WIN_H + 20,
 52	    };
 53	    return moveToward(target, pos, env.workArea, pet);
 54	  } catch {
 55	    return pos;
 56	  }
 57	}
 58	
 59	/// Persistent wander target. The engine calls wander() once per tick (30ms),
 60	/// so the target must survive across calls , otherwise the pet picks a new
 61	/// random destination every tick and jitters in place instead of walking.
 62	let wanderTarget: Point | null = null;
 63	
 64	/// Shared "resting until" deadline (ms timestamp). Set by a mode when the pet
 65	/// reaches a destination / edge and should pause. The engine loop keeps
 66	/// ticking at 30ms while resting, so drag, mood changes, and mode switches
 67	/// stay responsive , the modes just no-op until the deadline passes.
 68	let restUntil = 0;
 69	
 70	function inBounds(p: Point, bounds: Rect): boolean {
 71	  return p.x >= bounds.left && p.x <= bounds.right - WIN_W
 72	      && p.y >= bounds.top && p.y <= bounds.bottom - WIN_H;
 73	}
 74	
 75	/// Random walk within the work area. Walks to a target, idles, picks another.
 76	/// The target persists across ticks so the pet actually reaches it. Idling is
 77	/// done by setting `restUntil` (no blocking sleep) so the engine stays live.
 78	async function wander(ctx: ModeContext): Promise<Point> {
 79	  const { env, pos, pet } = ctx;
 80	  if (loadConfig().mode !== "wander") { wanderTarget = null; restUntil = 0; return pos; }
 81	  if (Date.now() < restUntil) return pos;
 82	  if (!wanderTarget || !inBounds(wanderTarget, env.workArea)) {
 83	    wanderTarget = randomTarget(env.workArea);
 84	  }
 85	  const target = wanderTarget;
 86	
 87	  const dx = target.x - pos.x;
 88	  const dy = target.y - pos.y;
 89	  const dist = Math.hypot(dx, dy);
 90	
 91	  if (dist < 6) {
 92	    wanderTarget = null;
 93	    restUntil = Date.now() + IDLE_MS_MIN + Math.random() * (IDLE_MS_MAX - IDLE_MS_MIN);
 94	    pet?.clearRow();
 95	    return pos;
 96	  }
 97	  return moveToward(target, pos, env.workArea, pet);
 98	}
 99	
100	/// Climb along the top edges of visible application windows, like Shimeji.
101	/// Walks horizontally until reaching the edge of a window, then either drops
102	/// to the next surface below or idles before reversing direction.
103	async function climb(ctx: ModeContext): Promise<Point> {
104	  const { env, pos, pet } = ctx;
105	  if (env.windows.length === 0) return wander(ctx);
106	  if (Date.now() < restUntil) return pos;
107	
108	  const surface = findSurfaceBelow(pos, env);
109	  if (!surface) return pos;
110	
111	  const dir = pickClimbDirection(pos, surface, env);
112	  const step = pxPerSec(loadConfig().speed) * DT_SEC;
113	  const nextX = pos.x + dir * step;
114	  const onEdge = nextX < surface.rect.left - 2 || nextX > surface.rect.right + 2;
115	
