   205	/// Logical size of the primary monitor's work area (DPI-divided). Returns a
   206	/// safe fallback (1920×1080) if the monitor can't be read , spawns must never
   207	/// land off-screen on display hotplug / headless CI.
   208	fn primary_work_area(app: &tauri::AppHandle) -> (f64, f64) {
   209	    app.primary_monitor()
   210	        .ok()
   211	        .flatten()
   212	        .and_then(|m| {
   213	            let s = m.size();
   214	            let sf = m.scale_factor();
   215	            if s.width > 0 && s.height > 0 {
   216	                Some((s.width as f64 / sf, s.height as f64 / sf))
   217	            } else {
   218	                None
   219	            }
   220	        })
   221	        .unwrap_or((1920.0, 1080.0))
   222	}
