   313	fn sync_desktop_pet_windows_impl(app: tauri::AppHandle, pets: Vec<DesktopPetWindow>) {
   314	    use std::collections::HashSet;
   315	    let wanted: HashSet<String> = pets.iter().map(|pet| pet_window_label(&pet.id)).collect();
   316	    for (label, window) in app.webview_windows() {
   317	        if is_pet_window(&label) && !wanted.contains(&label) {
   318	            let _ = window.close();
   319	        }
   320	    }
   321	    for (index, pet) in pets.iter().enumerate() {
   322	        if let Err(error) = build_desktop_pet_window(&app, pet, index) {
   323	            dlog(&format!("desktop pet window failed for {}: {error}", pet.id));
   324	        }
   325	    }
   326	}
