   402	/// Spawn the floating ball window if it doesn't exist yet. Position is restored
   403	/// from disk (clamped onto a monitor) or defaulted to the bottom-right corner.
   404	/// Must be called from a worker thread, like open_settings_impl.
   405	fn spawn_floating_ball_impl(app: tauri::AppHandle) {
   406	    if app.get_webview_window(FLOATING_BALL_LABEL).is_some() {
   407	        return;
   408	    }
   409	    let (sw, sh) = primary_work_area(&app);
   410	    let (x, y) = read_ball_pos()
   411	        .filter(|&(x, y)| x >= 0.0 && x <= sw && y >= 0.0 && y <= sh)
   412	        .unwrap_or_else(|| (sw - BALL_W - 24.0, sh - BALL_H - 80.0));
   413	    let _ = WebviewWindowBuilder::new(
   414	        &app,
   415	        FLOATING_BALL_LABEL,
   416	        WebviewUrl::App("floating-ball.html".into()),
   417	    )
   418	    .title("DesktopPet")
   419	    .inner_size(BALL_W, BALL_H)
   420	    .position(x.max(0.0), y.max(0.0))
   421	    .transparent(true)
   422	    .decorations(false)
   423	    .always_on_top(true)
   424	    .skip_taskbar(true)
   425	    .resizable(false)
   426	    .shadow(false)
   427	    .focused(false)
   428	    .build();
   429	}
