   488	/// Show the popover (the macOS menu-bar popover equivalent) near the cursor.
   489	fn show_popover(app: &tauri::AppHandle) {
   490	    let win = match app.get_webview_window("popover") {
   491	        Some(w) => w,
   492	        None => {
   493	            match WebviewWindowBuilder::new(app, "popover", WebviewUrl::App("popover.html".into()))
   494	                .title("DesktopPet")
   495	                .inner_size(300.0, 430.0)
   496	                .decorations(false)
   497	                .transparent(true)
   498	                .always_on_top(true)
   499	                .skip_taskbar(true)
   500	                .resizable(false)
   501	                .focused(true)
   502	                .visible(false)
   503	                .build()
   504	            {
   505	                Ok(w) => {
   506	                    dlog("popover: window created");
   507	                    // Transient popover: losing focus hides it (Rust-side net,
   508	                    // independent of the webview's own blur listener).
   509	                    let wh = w.clone();
   510	                    w.on_window_event(move |ev| {
   511	                        if let tauri::WindowEvent::Focused(false) = ev {
   512	                            let _ = wh.hide();
   513	                        }
   514	                    });
   515	                    w
   516	                }
   517	                Err(e) => {
   518	                    dlog(&format!("popover: BUILD FAILED: {e}"));
   519	                    return;
   520	                }
   521	            }
   522	        }
   523	    };
   524	    // Place near the cursor, clamped onto the monitor under it.
   525	    if let Ok(cur) = app.cursor_position() {
   526	        let sf = win.scale_factor().unwrap_or(1.0);
   527	        let (w, h) = (300.0 * sf, 430.0 * sf);
   528	        let mut x = cur.x - w / 2.0;
   529	        let mut y = cur.y - h - 12.0; // prefer above the cursor (tray at bottom)
   530	        if let Ok(Some(mon)) = app.monitor_from_point(cur.x, cur.y) {
   531	            let mp = mon.position();
   532	            let ms = mon.size();
   533	            if y < mp.y as f64 {
   534	                y = cur.y + 12.0; // no room above , drop below
   535	            }
   536	            x = x.max(mp.x as f64).min(mp.x as f64 + ms.width as f64 - w);
   537	            y = y.max(mp.y as f64).min(mp.y as f64 + ms.height as f64 - h);
   538	        }
   539	        let _ = win.set_position(PhysicalPosition::new(x, y));
   540	    }
   541	    let _ = win.show();
   542	    let _ = win.set_focus();
   543	    let _ = win.emit("popover-shown", ());
   544	}
   545	
   546	#[tauri::command]
   547	async fn open_popover(app: tauri::AppHandle) {
   548	    dlog("open_popover called");
   549	    std::thread::spawn(move || show_popover(&app));
   550	}
