   488	/// Show the popover (the macOS menu-bar popover equivalent) near the cursor.
   489	fn show_popover(app: &tauri::AppHandle) {
   490	    let win = match app.get_webview_window("popover") {
   491	        Some(w) => w,
   492	        None => {
   493	            match WebviewWindowBuilder::new(app, "popover", WebviewUrl::App("popover.html".into()))
   494	                .title("DesktopPet")
   495	                .inner_size(300.0, 430.0)
   496	                .decorations(false)
   497	                .transparent(true)
   498	                .always_on_top(true)
   499	                .skip_taskbar(true)
   500	                .resizable(false)
   501	                .focused(true)
   502	                .visible(false)
   503	                .build()
   504	            {
   505	                Ok(w) => {
   506	                    dlog("popover: window created");
   507	                    // Transient popover: losing focus hides it (Rust-side net,
   508	                    // independent of the webview's own blur listener).
   509	                    let wh = w.clone();
   510	                    w.on_window_event(move |ev| {
   511	                        if let tauri::WindowEvent::Focused(false) = ev {
   512	                            let _ = wh.hide();
   513	                        }
   514	                    });
   515	                    w
   516	                }
