   519	                    return;
   520	                }
   521	            }
   522	        }
   523	    };
   524	    // Place near the cursor, clamped onto the monitor under it.
   525	    if let Ok(cur) = app.cursor_position() {
   526	        let sf = win.scale_factor().unwrap_or(1.0);
   527	        let (w, h) = (300.0 * sf, 430.0 * sf);
   528	        let mut x = cur.x - w / 2.0;
   529	        let mut y = cur.y - h - 12.0; // prefer above the cursor (tray at bottom)
