     1	// Simple speech bubble (port of the macOS ChatBubble): a single capsule line
     2	// driven by `renderLine`.
     3	
     4	export function invalidateBubbleConfig(): void {
     5	  // No cached config anymore (appearance lives in CSS variables via
     6	  // `applyBubble`); kept as a no-op so Settings can call it unconditionally.
     7	}
     8	
     9	export class BubbleRenderer {
    10	  /// Set by the app when a re-render is desired (e.g. bubble needs repaint).
    11	  dirty = false;
    12	
    13	  constructor(private root: HTMLElement) {}
    14	
    15	  /// Single plain line (idle / done / celebrate), the mac ChatBubble.
    16	  /// Re-entrant: repeated calls with the same text are no-ops (no DOM churn,
    17	  /// no flicker), only an actual text change cross-fades.
    18	  renderLine(text: string) {
    19	    let line = this.root.querySelector<HTMLElement>(".single-line");
    20	    if (!line) {
    21	      this.clear(); // leaving rows mode, rebuild as a single capsule line
    22	      line = document.createElement("div");
    23	      line.className = "single-line";
    24	      line.textContent = text;
    25	      this.root.appendChild(line);
    26	      this.root.classList.add("capsule");
    27	      this.root.hidden = false;
    28	      return;
    29	    }
    30	    this.root.hidden = false;
    31	    if (line.textContent !== text) {
    32	      // Cross-fade the text swap (mac contentTransition(.opacity)).
    33	      line.classList.add("fade");
    34	      line.textContent = text;
    35	      requestAnimationFrame(() => line!.classList.remove("fade"));
    36	    }
    37	  }
    38	
    39	  hide() {
    40	    this.clear();
    41	    this.root.hidden = true;
    42	  }
    43	
    44	  private clear() {
    45	    this.root.classList.remove("capsule");
    46	    this.root.textContent = "";
    47	  }
    48	}
